__NUXT_JSONP__("/finanzas-publicas/eventos/empresas_de_monterrey_ciudad_de_mexico_y_quintana_roo_fortalecen_sus_sistemas_de_integridad_y_cultura_etica", (function(a,b,c,d){return {data:[{post:{slug:"empresas_de_monterrey_ciudad_de_mexico_y_quintana_roo_fortalecen_sus_sistemas_de_integridad_y_cultura_etica",title:"Empresas de Monterrey, Ciudad de México y Quintana Roo fortalecen sus sistemas de integridad y cultura ética",date:"2025-10-03T20:05:49.023Z",img:"https:\u002F\u002Fucarecdn.com\u002F3c4b70dc-200d-4e12-a0f2-d0d20abdaccc\u002F",autor:"Ethos",category:"finanzas-publicas",extracto:"19 empresas de Monterrey, Ciudad de México y Quintana Roo concluyeron el Programa de Integridad Empresarial 2025, en el que fortalecieron sus sistemas de integridad y cultura ética con el acompañamiento de Hágamoslo Bien, Ethos y el Comité de Participación Ciudadana de Quintana Roo.",toc:[],body:{type:"root",children:[{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"Luego de cuatro meses de acompañamiento, 19 empresas de Monterrey, Ciudad de México y Quintana Roo concluyeron su participación en el Programa de Integridad Empresarial 2025, del proyecto Bien en tu Empresa, organizado por Hágamoslo Bien en colaboración con Ethos y el Comité de Participación Ciudadana de Quintana Roo."}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"Durante este proceso, las y los participantes fortalecieron sus sistemas de integridad mediante diagnósticos, asesorías y capacitaciones personalizadas, enfocadas en las necesidades específicas de cada empresa. Además, reflexionaron sobre la relevancia de promover una cultura ética entre sus equipos de trabajo y de garantizar el cumplimiento de sus obligaciones legales y regulatorias para generar mayor confianza entre clientes, inversionistas y aliados."}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"La ceremonia de clausura incluyó conferencias en Monterrey y Ciudad de México. En Monterrey, Emiliano Montes de Oca, coordinador de proyectos anticorrupción en Ethos, presentó la conferencia «Riesgos de corrupción en las relaciones público-privadas y la importancia del compliance», donde analizó los desafíos que enfrentan las pequeñas y medianas empresas al abrir y operar sus negocios, especialmente en trámites y procesos con el sector público."}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"En la Ciudad de México, Bernardo Álvarez del Castillo, Chief Compliance Officer de Grupo Expansión, impartió la ponencia «El compliance frente a la interminable corrupción». Durante su intervención, compartió casos reales de empresas que enfrentaron consecuencias negativas por no contar con buenas prácticas de cumplimiento, códigos de ética y políticas anticorrupción efectivas."}]},{type:a,value:b},{type:c,tag:d,props:{},children:[{type:a,value:"El Programa de Integridad Empresarial 2025 forma parte de la iniciativa «Fortaleciendo a #OSC y periodistas en anticorrupción», desarrollada por Ethos con el apoyo de la National Endowment for Democracy."}]},{type:a,value:b}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fempresas_de_monterrey_ciudad_de_mexico_y_quintana_roo_fortalecen_sus_sistemas_de_integridad_y_cultura_etica",extension:".md",createdAt:"2025-11-25T01:24:03.255Z",updatedAt:"2025-11-25T01:24:03.256Z"}}],fetch:{},mutations:[]}}("text","\n","element","p")));